const inputItems = $input.all();

function getHeader(headers, headerName) {
  const matchedHeader = Object.entries(headers).find(
    ([key]) => key.toLowerCase() === headerName.toLowerCase()
  );

  return matchedHeader?.[1];
}

function getClientIp(headers) {
  const forwardedFor = getHeader(headers, 'x-forwarded-for');

  if (typeof forwardedFor === 'string' && forwardedFor.trim()) {
    return forwardedFor.split(',')[0].trim();
  }

  return getHeader(headers, 'x-real-ip') ?? 'unknown';
}

return inputItems.map((item, index) => {
  const headers = item.json?.headers ?? {};
  const suppliedRequestId = getHeader(headers, 'x-request-id');

  const requestId =
    typeof suppliedRequestId === 'string' && suppliedRequestId.trim()
      ? suppliedRequestId.trim()
      : `ccrf_${Date.now()}_${index}_${Math.random()
          .toString(36)
          .slice(2, 10)}`;

  item.json.securityContext = {
    authenticated: true,
    authenticationMethod: 'webhook-header-auth',
    requestId,
    requesterIp: getClientIp(headers),
    userAgent: getHeader(headers, 'user-agent') ?? 'unknown',
    receivedAt: new Date().toISOString(),
  };

  return item;
});

const inputItems = $input.all();

const ALLOWED_FILE_TYPES = {
  pdf: ['application/pdf'],
  docx: [
    'application/vnd.openxmlformats-officedocument.wordprocessingml.document',
  ],
  txt: ['text/plain'],
};

const MAX_FILE_SIZE_BYTES = 20 * 1024 * 1024; // 20 MB

function getFileSizeInBytes(fileSize) {
  if (typeof fileSize === 'number') return fileSize;
  if (typeof fileSize !== 'string') return 0;

  const match = fileSize.trim().match(/^([\d.]+)\s*(B|KB|MB|GB)?$/i);
  if (!match) return 0;

  const value = Number(match[1]);
  const unit = (match[2] ?? 'B').toUpperCase();
  const multipliers = {
    B: 1,
    KB: 1024,
    MB: 1024 ** 2,
    GB: 1024 ** 3,
  };

  return Math.round(value * multipliers[unit]);
}

return inputItems.map((item) => {
  const binaryFiles = Object.entries(item.binary ?? {});

  if (binaryFiles.length === 0) {
    throw new Error('Validation failed: no contract file was uploaded.');
  }

  const selectedFile =
    binaryFiles.find(([key]) => key === 'contractFile') ?? binaryFiles[0];

  const [binaryPropertyName, file] = selectedFile;
  const fileName = file.fileName ?? 'uploaded-contract';
  const extension = fileName.split('.').pop()?.toLowerCase();
  const mimeType = (file.mimeType ?? '').toLowerCase();
  const fileSizeBytes = getFileSizeInBytes(file.fileSize ?? file.size);

  if (!extension || !ALLOWED_FILE_TYPES[extension]) {
    throw new Error(
      'Validation failed: only PDF, DOCX, and TXT contract files are accepted.'
    );
  }

  if (!ALLOWED_FILE_TYPES[extension].includes(mimeType)) {
    throw new Error(
      `Validation failed: file extension .${extension} does not match MIME type ${mimeType || 'unknown'}.`
    );
  }

  if (fileSizeBytes > MAX_FILE_SIZE_BYTES) {
    throw new Error(
      'Validation failed: the contract exceeds the 20 MB upload limit.'
    );
  }

  item.json.document = {
    binaryPropertyName,
    fileName,
    extension,
    mimeType,
    fileSizeBytes,
  };

  item.json.fileValidation = {
    valid: true,
    validatedAt: new Date().toISOString(),
    acceptedTypes: ['pdf', 'docx', 'txt'],
    maxFileSizeBytes: MAX_FILE_SIZE_BYTES,
  };

  return item;
});

const driveUploadItems = $input.all();
const preservedContractItems = $items(
  '04B — Preserve Contract Context & Scan Result',
  0,
  0
);

const FORMAT_RULES = {
  pdf: {
    mimeTypes: ['application/pdf'],
    processingRoute: 'pdf-native-text-extraction',
    requiresTextExtraction: true,
    supportsOcrFallback: true,
  },
  docx: {
    mimeTypes: [
      'application/vnd.openxmlformats-officedocument.wordprocessingml.document',
    ],
    processingRoute: 'docx-text-extraction',
    requiresTextExtraction: true,
    supportsOcrFallback: false,
  },
  txt: {
    mimeTypes: ['text/plain'],
    processingRoute: 'direct-text-processing',
    requiresTextExtraction: false,
    supportsOcrFallback: false,
  },
};

if (preservedContractItems.length === 0) {
  throw new Error(
    'Format detection failed: preserved contract context from Node 04B is missing.'
  );
}

return driveUploadItems.map((driveUploadItem, index) => {
  const preservedContractItem =
    preservedContractItems[index] ?? preservedContractItems[0];

  const document = preservedContractItem.json?.document;
  const binaryPropertyName = document?.binaryPropertyName ?? 'contractFile';
  const binaryFile = preservedContractItem.binary?.[binaryPropertyName];

  if (!document || !binaryFile) {
    throw new Error(
      'Format detection failed: original document metadata or binary file is missing.'
    );
  }

  const extension = String(
    document.extension ?? binaryFile.fileExtension ?? ''
  ).toLowerCase();

  const mimeType = String(
    document.mimeType ?? binaryFile.mimeType ?? ''
  ).toLowerCase();

  const formatRule = FORMAT_RULES[extension];

  if (!formatRule || !formatRule.mimeTypes.includes(mimeType)) {
    throw new Error(
      `Unsupported or mismatched document format: .${extension} / ${mimeType}.`
    );
  }

  return {
    json: {
      ...preservedContractItem.json,

      storage: {
        provider: 'google-drive',
        fileId: driveUploadItem.json?.id ?? null,
        fileName: driveUploadItem.json?.name ?? document.fileName,
        webViewLink: driveUploadItem.json?.webViewLink ?? null,
        storedAt: new Date().toISOString(),
      },

      fileFormat: {
        detectedFormat: extension,
        mimeType,
        binaryPropertyName,
        processingRoute: formatRule.processingRoute,
        requiresTextExtraction: formatRule.requiresTextExtraction,
        supportsOcrFallback: formatRule.supportsOcrFallback,
        scanStatus:
          extension === 'pdf'
            ? 'pending-native-text-check'
            : 'not-applicable',
        detectedAt: new Date().toISOString(),
      },
    },

    binary: preservedContractItem.binary,
  };
});

