const inputItems = $input.all();

function createFingerprint(value) {
  let hash = 2166136261;

  for (let index = 0; index < value.length; index += 1) {
    hash ^= value.charCodeAt(index);
    hash = Math.imul(hash, 16777619);
  }

  return `fnv1a-${(hash >>> 0).toString(16).padStart(8, '0')}`;
}

function normalizeContractText(value) {
  return value
    .normalize('NFKC')
    .replace(/\u00A0/g, ' ')                // non-breaking spaces
    .replace(/[\u200B-\u200D\uFEFF]/g, '')  // invisible characters
    .replace(/\r\n?/g, '\n')
    .replace(/([A-Za-z])-\n([a-z])/g, '$1$2') // line-break hyphenation
    .replace(/[ \t]+\n/g, '\n')
    .replace(/\n[ \t]+/g, '\n')
    .replace(/[ \t]{2,}/g, ' ')
    .replace(/\n{3,}/g, '\n\n')
    .replace(/^\s+|\s+$/g, '');
}

return inputItems.map((item) => {
  const rawText = String(item.json?.extraction?.text ?? '');

  if (!rawText.trim()) {
    throw new Error(
      'Text normalization failed: no extracted contract text is available.'
    );
  }

  const normalizedText = normalizeContractText(rawText);
  const wordCount = normalizedText
    .split(/\s+/)
    .filter(Boolean).length;

  if (wordCount < 20) {
    throw new Error(
      'Text normalization failed: extracted content is too short for reliable contract analysis.'
    );
  }

  item.json.contractText = {
    rawCharacterCount: rawText.length,
    normalizedCharacterCount: normalizedText.length,
    wordCount,
    fingerprint: createFingerprint(normalizedText),
    language: item.json?.fileFormat?.detectedFormat === 'txt'
      ? 'unknown'
      : 'pending-detection',
    normalizedAt: new Date().toISOString(),
  };

  item.json.normalizedText = normalizedText;

  return item;
});

