  throw new Error(
    'Contract context recovery failed: Node 03 did not provide an input item.'
  );
}

return virusTotalItems.map((virusTotalItem, index) => {
  const originalContractItem =
    originalContractItems[index] ?? originalContractItems[0];

  const analysisId = virusTotalItem.json?.data?.id;

  if (!analysisId) {
    throw new Error(
      'VirusTotal submission failed: the response does not include an analysis ID.'
    );
  }

  if (!originalContractItem.binary?.contractFile) {
    throw new Error(
      'Contract context recovery failed: contractFile binary data is missing.'
    );
  }

  return {
    json: {
      ...originalContractItem.json,

      virusTotal: {
        submissionStatus: 'queued',
        analysisId,
        analysisUrl:
          virusTotalItem.json?.data?.links?.self ?? null,
        submittedAt: new Date().toISOString(),
      },
    },

    binary: originalContractItem.binary,
  };
});

const inputItems = $input.all();
const MINIMUM_NATIVE_TEXT_LENGTH = 120;

return inputItems.map((item) => {
  const extractedText = String(item.json?.text ?? '').trim();
  const nativeTextLength = extractedText.length;
  const requiresOcr = nativeTextLength < MINIMUM_NATIVE_TEXT_LENGTH;

  item.json.extractionQuality = {
    nativeTextLength,
    minimumExpectedTextLength: MINIMUM_NATIVE_TEXT_LENGTH,
    requiresOcr,
    decision: requiresOcr ? 'ocr-required' : 'native-text-sufficient',
    reason: requiresOcr
      ? 'Native PDF extraction returned insufficient readable text.'
      : 'Native PDF extraction returned sufficient readable text.',
    assessedAt: new Date().toISOString(),
  };

  return item;
});

const extractionItems = $input.all();
const originalFormatItems = $items('06 — Detect File Format', 0, 0);

if (originalFormatItems.length === 0) {
  throw new Error(
    'Extraction consolidation failed: original document context is unavailable.'
  );
}

return extractionItems.map((extractionItem, index) => {
  const originalItem =
    originalFormatItems[index] ?? originalFormatItems[0];

  const extractedText = String(extractionItem.json?.text ?? '').trim();
  const extractionQuality = extractionItem.json?.extractionQuality ?? {};

  if (!originalItem.binary?.contractFile) {
    throw new Error(
      'Extraction consolidation failed: original contract binary is missing.'
    );
  }

  return {
    json: {
      ...originalItem.json,

      extraction: {
        status: extractionQuality.requiresOcr
          ? 'ocr-required'
          : 'ready-for-normalization',

        source: extractionQuality.requiresOcr
          ? 'native-text-insufficient'
          : 'native-pdf-text',

        text: extractedText,
        textLength: extractedText.length,
        pageCount: extractionItem.json?.numpages ?? null,
        pdfMetadata: extractionItem.json?.info ?? {},
        quality: extractionQuality,
        consolidatedAt: new Date().toISOString(),
      },
    },

    binary: originalItem.binary,
  };
});

const items = $input.all();

return items.map((item) => {
  const rawContent = item.json?.choices?.[0]?.message?.content ?? "";

  let parsed;

  try {
    if (typeof rawContent === "string") {
      parsed = JSON.parse(rawContent);
    } else {
      parsed = rawContent;
    }
  } catch (error) {
    throw new Error(
      `Language detection JSON parsing failed. Received: ${rawContent}`
    );
  }

  const language = String(parsed?.language ?? "").trim();

  const isEnglish =
    parsed?.isEnglish === true ||
    String(parsed?.isEnglish ?? "").toLowerCase() === "true";

  const confidence = Number(parsed?.confidence ?? 0);

  return {
    json: {
      ...item.json,

      detectedLanguage: language,
      isEnglish: isEnglish,
      languageConfidence: confidence,

      languageDetection: {
        language: language,
        isEnglish: isEnglish,
        confidence: confidence
      }
    }
  };
});

