/**
 * NODE 17 — Parse Contract Metadata
 * Production-grade metadata parser and normalization layer
 */

// =========================================================
// 1. READ NODE 16 GEMINI RESPONSE
// =========================================================

const geminiResponse = $json;

const rawContent =
  geminiResponse?.choices?.[0]?.message?.content;

if (!rawContent) {
  throw new Error(
    'Node 16 did not return choices[0].message.content.'
  );
}

// =========================================================
// 2. CLEAN GEMINI RESPONSE
// =========================================================

let cleanedContent = String(rawContent).trim();

// Remove accidental Markdown code fences
cleanedContent = cleanedContent
  .replace(/^```json\s*/i, '')
  .replace(/^```\s*/i, '')
  .replace(/\s*```$/i, '')
  .trim();

// =========================================================
// 3. PARSE JSON SAFELY
// =========================================================

let metadata;

try {
  metadata = JSON.parse(cleanedContent);
} catch (error) {

  // Recovery attempt if Gemini added unwanted text
  const firstBrace = cleanedContent.indexOf('{');
  const lastBrace = cleanedContent.lastIndexOf('}');

  if (firstBrace === -1 || lastBrace === -1) {
    throw new Error(
      `Node 16 returned invalid JSON.\n\nRaw response:\n${cleanedContent}`
    );
  }

  const extractedJson = cleanedContent.slice(
    firstBrace,
    lastBrace + 1
  );

  try {
    metadata = JSON.parse(extractedJson);
  } catch (parseError) {
    throw new Error(
      `Failed to parse Node 16 response as JSON.\n\n` +
      `Parser error: ${parseError.message}\n\n` +
      `Raw response:\n${cleanedContent}`
    );
  }
}

// =========================================================
// 4. NORMALIZE CONTRACT TYPE
// =========================================================

const contractType =
  typeof metadata?.contractType === 'string' &&
  metadata.contractType.trim()
    ? metadata.contractType.trim()
    : 'Unknown';

// =========================================================
// 5. NORMALIZE PARTIES
// =========================================================

const parties = Array.isArray(metadata?.parties)
  ? metadata.parties
      .filter(p =>
        p &&
        typeof p === 'object' &&
        typeof p.name === 'string' &&
        p.name.trim()
      )
      .map(p => ({
        name: p.name.trim(),
        role:
          typeof p.role === 'string'
            ? p.role.trim()
            : ''
      }))
  : [];

// =========================================================
// 6. NORMALIZE DATES
// =========================================================

const dates = Array.isArray(metadata?.dates)
  ? metadata.dates
      .filter(d =>
        d &&
        typeof d === 'object'
      )
      .map(d => ({
        type:
          typeof d.type === 'string'
            ? d.type.trim()
            : '',
        date:
          typeof d.date === 'string'
            ? d.date.trim()
            : ''
      }))
      .filter(d => d.type || d.date)
  : [];

// =========================================================
// 7. NORMALIZE JURISDICTION
// =========================================================

const jurisdiction =
  metadata?.jurisdiction &&
  typeof metadata.jurisdiction === 'object'
    ? {
        governingLaw:
          typeof metadata.jurisdiction.governingLaw === 'string'
            ? metadata.jurisdiction.governingLaw.trim()
            : '',

        jurisdiction:
          typeof metadata.jurisdiction.jurisdiction === 'string'
            ? metadata.jurisdiction.jurisdiction.trim()
            : ''
      }
    : {
        governingLaw: '',
        jurisdiction: ''
      };

// =========================================================
// 8. GET ORIGINAL CONTRACT TEXT FROM NODE 15
// =========================================================

const contractText =
  $('15 — Choose Analysis Text')
    .item
    .json
    ?.choices?.[0]
    ?.message
    ?.content || '';

if (!contractText.trim()) {
  throw new Error(
    'Original contract text could not be retrieved from Node 15 — Choose Analysis Text.'
  );
}

// =========================================================
// 9. BASIC DATA QUALITY CHECK
// =========================================================

const dataQuality = {
  hasContractType: contractType !== 'Unknown',
  partyCount: parties.length,
  dateCount: dates.length,
  hasGoverningLaw: Boolean(jurisdiction.governingLaw),
  hasJurisdiction: Boolean(jurisdiction.jurisdiction)
};

// =========================================================
// 10. FINAL NORMALIZED OUTPUT
// =========================================================

return [
  {
    json: {
      contractType,

      parties,

      dates,

      jurisdiction,

      contractText,

      dataQuality,

      metadataExtraction: {
        source: 'Gemini',
        status: 'success',
        parsed: true,
        parserVersion: '1.0',
        extractedAt: new Date().toISOString()
      }
    }
  }
];

/**
 * NODE 18 — Contract Clause Segmentation Engine
 *
 * Purpose:
 * - Segment the normalized contract into analyzable clauses
 * - Preserve section numbers and headings
 * - Handle numbered, lettered and unnumbered sections
 * - Avoid creating meaningless fragments
 * - Preserve all metadata from Node 17
 */

// =========================================================
// 1. INPUT VALIDATION
// =========================================================

const input = $input.first().json;

const contractText = String(input.contractText || '').trim();

if (!contractText) {
  throw new Error(
    'Node 18: contractText is missing from Node 17.'
  );
}

// =========================================================
// 2. NORMALIZE TEXT
// =========================================================

const normalizedText = contractText
  .replace(/\r\n/g, '\n')
  .replace(/\r/g, '\n')
  .replace(/[ \t]+/g, ' ')
  .replace(/\n{3,}/g, '\n\n')
  .trim();

// =========================================================
// 3. REMOVE NON-CONTRACT TEST HEADER WHEN PRESENT
// =========================================================

const lines = normalizedText
  .split('\n')
  .map(line => line.trim())
  .filter(Boolean);

// =========================================================
// 4. SECTION DETECTION
// =========================================================
//
// Supports patterns such as:
//
// 1. Services
// 2. Fees and Payment
// 3. Term and Automatic Renewal
//
// Also supports:
//
// 1 Services
// 1) Services
// 1 - Services
// ARTICLE 1
// SECTION 1
// A. Confidentiality
//
// =========================================================

const sectionPattern =
  /^(?:(?:SECTION|ARTICLE)\s+)?(\d+(?:\.\d+)*|[A-Z])[\.\):\-]\s*(.+)$/i;

const detectedSections = [];

let currentSection = null;

for (const line of lines) {

  const match = line.match(sectionPattern);

  if (match) {

    // Save previous section
    if (currentSection) {
      detectedSections.push(currentSection);
    }

    currentSection = {
      sectionNumber: match[1],
      heading: match[2].trim(),
      lines: []
    };

  } else if (currentSection) {

    currentSection.lines.push(line);

  }
}

// Save final section
if (currentSection) {
  detectedSections.push(currentSection);
}

// =========================================================
// 5. FALLBACK SEGMENTATION
// =========================================================
//
// If no formal sections were detected, split the document
// into logical paragraphs instead of returning one huge item.
// =========================================================

if (detectedSections.length === 0) {

  const paragraphs = normalizedText
    .split(/\n\s*\n/)
    .map(p => p.trim())
    .filter(p => p.length > 40);

  if (paragraphs.length === 0) {
    throw new Error(
      'Node 18: Unable to identify contract clauses or meaningful paragraphs.'
    );
  }

  return paragraphs.map((paragraph, index) => ({
    json: {
      ...input,

      clause: {
        clauseId: `CL-${String(index + 1).padStart(3, '0')}`,
        sectionNumber: '',
        heading: `Clause ${index + 1}`,
        text: paragraph,
        characterCount: paragraph.length,
        wordCount: paragraph.split(/\s+/).length
      },

      segmentation: {
        method: 'paragraph-fallback',
        totalClauses: paragraphs.length
      }
    }
  }));
}

// =========================================================
// 6. BUILD STRUCTURED CLAUSES
// =========================================================

const clauses = detectedSections
  .map((section, index) => {

    const body = section.lines.join(' ').trim();

    const fullText = body
      ? `${section.sectionNumber}. ${section.heading}\n${body}`
      : `${section.sectionNumber}. ${section.heading}`;

    return {
      clauseId:
        `CL-${String(index + 1).padStart(3, '0')}`,

      sectionNumber:
        section.sectionNumber,

      heading:
        section.heading,

      text:
        fullText.trim(),

      characterCount:
        fullText.length,

      wordCount:
        fullText.split(/\s+/).filter(Boolean).length
    };
  })
  .filter(clause => clause.text.length > 20);

// =========================================================
// 7. QUALITY CONTROL
// =========================================================

if (clauses.length === 0) {
  throw new Error(
    'Node 18: Clause segmentation produced zero usable clauses.'
  );
}

// =========================================================
// 8. RETURN ONE ITEM PER CLAUSE
// =========================================================

return clauses.map(clause => ({
  json: {

    // Preserve all metadata from Node 17
    contractType: input.contractType,
    parties: input.parties,
    dates: input.dates,
    jurisdiction: input.jurisdiction,
    contractText: input.contractText,
    dataQuality: input.dataQuality,
    metadataExtraction: input.metadataExtraction,

    // Current clause
    clause,

    // Processing information
    segmentation: {
      method: 'section-based',
      totalClauses: clauses.length,
      currentClauseIndex: clauses.indexOf(clause) + 1,
      status: 'ready_for_risk_analysis'
    }
  }
}));

