const items = $input.all();

const output = [];

for (const item of items) {
  const rawContent = item.json?.choices?.[0]?.message?.content ?? "";

  if (!rawContent) {
    throw new Error("Node 19 returned empty AI content.");
  }

  let parsed;

  try {
    parsed =
      typeof rawContent === "string"
        ? JSON.parse(rawContent)
        : rawContent;
  } catch (error) {
    throw new Error(
      `Failed to parse Node 19 JSON: ${rawContent}`
    );
  }

  const analyses = Array.isArray(parsed?.analyses)
    ? parsed.analyses
    : [];

  if (analyses.length === 0) {
    throw new Error("No clause risk analyses found in Node 19 output.");
  }

  for (const analysis of analyses) {
    output.push({
      json: {
        clauseId: String(analysis.clauseId || ""),
        sectionNumber: String(analysis.sectionNumber || ""),
        heading: String(analysis.heading || ""),

        riskLevel: String(analysis.riskLevel || "LOW"),

        riskScore: Number(analysis.riskScore || 0),

        riskCategory: String(
          analysis.riskCategory || "General"
        ),

        issue: String(
          analysis.issue || ""
        ),

        recommendation: String(
          analysis.recommendation || ""
        ),

        riskAnalysisStatus: "parsed"
      }
    });
  }
}

return output;

const items = $input.all();

return items.map((item, index) => {
