      clauseId: data.clauseId || "",
      sectionNumber: data.sectionNumber || "",
      heading: data.heading || "",

      risk: {
        level: data.riskLevel || priority,
        score: riskScore,
        category: data.riskCategory || "General"
      },

      issue: data.issue || "",

      recommendation: data.recommendation || "",

      priority,

      findingStatus: "identified"
    }
  };
});

const items = $input.all();

if (items.length === 0) {
  throw new Error("No findings received.");
}

const findings = items.map(item => item.json);

const counts = {
  LOW: 0,
  MEDIUM: 0,
  HIGH: 0,
  CRITICAL: 0
};

let totalScore = 0;
let highestRisk = null;

for (const finding of findings) {
  const level = String(
    finding.risk?.level || "LOW"
  ).toUpperCase();

  const score = Math.max(
    0,
    Math.min(100, Number(finding.risk?.score || 0))
  );

  if (counts[level] !== undefined) {
    counts[level]++;
  }

  totalScore += score;

  if (
    highestRisk === null ||
    score > highestRisk.score
  ) {
    highestRisk = {
      clauseId: finding.clauseId || "",
      sectionNumber: finding.sectionNumber || "",
      heading: finding.heading || "",
      score,
      level
    };
  }
}

const averageScore = Number(
  (totalScore / findings.length).toFixed(2)
);

return [
  {
    json: {
      totalClausesAnalyzed: findings.length,

      riskDistribution: counts,

      totalRiskScore: totalScore,

      averageRiskScore: averageScore,

      highestRiskClause: highestRisk,

      highRiskCount:
        counts.HIGH + counts.CRITICAL,

      criticalRiskCount:
        counts.CRITICAL,

      summaryStatus: "aggregated"
    }
  }
];

