if (criticalCount > 0) {
  overallScore += Math.min(15, criticalCount * 5);
}

if (highRiskCount > 0) {
  overallScore += Math.min(10, highRiskCount * 2);
}

overallScore = Math.max(
  0,
  Math.min(100, Number(overallScore.toFixed(2)))
);

let overallRiskLevel;

if (overallScore >= 75) {
  overallRiskLevel = "CRITICAL";
} else if (overallScore >= 50) {
  overallRiskLevel = "HIGH";
} else if (overallScore >= 25) {
  overallRiskLevel = "MEDIUM";
} else {
  overallRiskLevel = "LOW";
}

